/** 扁平化的线路-站点记录，带上所属线路信息；顺序与 Excel 一致。 */
export const subwayStations = subwayLines.flatMap((line) =>
  line.stations.map((station) => ({ line_id: line.line_id, line_name: line.line_name, ...station })),
);

/** 有 WGS84 坐标的记录子集；仅供后续“附近有什么”阶段使用，不参与命运模式抽签。 */
export const subwayStationsWithCoordinates = subwayStations.filter(
  (station) => station.latitude !== null && station.longitude !== null,
);
